import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import Layout from '../../components/Layout';
import StatusBadge from '../../components/StatusBadge';
import API from '../../api/axios';

export default function CustomerOrderDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [order, setOrder] = useState(null);
  const [loading, setLoading] = useState(true);
  const [resending, setResending] = useState(false);

  useEffect(() => {
    API.get(`/customer/orders/${id}`)
      .then(({ data }) => setOrder(data.order))
      .catch(() => navigate('/customer/orders'))
      .finally(() => setLoading(false));
  }, [id]); // eslint-disable-line

  const handleResendWhatsApp = async (type) => {
    setResending(true);
    try {
      const { data } = await API.post(`/quotation/${id}/resend`, { type });
      toast.success(data.message);
    } catch (err) {
      toast.error(err.response?.data?.message || 'Failed to resend');
    } finally {
      setResending(false);
    }
  };

  if (loading) return <Layout title="Order Detail"><div className="spinner" /></Layout>;
  if (!order) return <Layout title="Order Detail"><div className="alert alert-error">Order not found.</div></Layout>;

  return (
    <Layout title={`Order ${order.orderNumber}`}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '1.5rem', flexWrap: 'wrap' }}>
        <button className="btn btn-ghost btn-sm" onClick={() => navigate('/customer/orders')}>← My Orders</button>
        <h1 className="page-title" style={{ margin: 0 }}>{order.orderNumber}</h1>
        <StatusBadge status={order.status} />
      </div>

      <div className="grid-2" style={{ alignItems: 'start' }}>
        {/* Left: Items */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
          <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
            <div style={{ padding: '1rem 1.25rem', borderBottom: '1px solid #f3f4f6' }}>
              <h3 style={{ fontWeight: 700, fontSize: '0.95rem' }}>
                Order Items — {order.storeName}
              </h3>
            </div>
            <table>
              <thead>
                <tr>
                  <th>Item</th>
                  <th>Qty</th>
                  <th>Price</th>
                  <th>Subtotal</th>
                </tr>
              </thead>
              <tbody>
                {order.items.map((item, i) => (
                  <tr key={i}>
                    <td>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                        {item.image ? (
                          <img src={`/uploads/${item.image}`} alt="" style={{ width: 32, height: 32, borderRadius: '0.35rem', objectFit: 'cover' }} />
                        ) : (
                          <div style={{ width: 32, height: 32, background: '#f3f4f6', borderRadius: '0.35rem', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#9ca3af', fontSize: '0.9rem' }}>📦</div>
                        )}
                        <span style={{ fontWeight: 500, fontSize: '0.875rem' }}>{item.name}</span>
                      </div>
                    </td>
                    <td style={{ fontSize: '0.875rem' }}>{item.quantity} {item.unit}</td>
                    <td style={{ fontSize: '0.875rem' }}>{item.price?.toFixed(2)}</td>
                    <td style={{ fontWeight: 700, fontSize: '0.875rem' }}>{item.subtotal?.toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
            <div style={{ padding: '1rem 1.25rem', borderTop: '1px solid #f3f4f6' }}>
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: '0.3rem', fontSize: '0.875rem' }}>
                <div>Subtotal: <strong>{order.subtotal?.toFixed(2)}</strong></div>
                {order.tax > 0 && <div>Tax: <strong>{order.tax?.toFixed(2)}</strong></div>}
                {order.discount > 0 && <div>Discount: <strong>-{order.discount?.toFixed(2)}</strong></div>}
                <div style={{ fontSize: '1.1rem', borderTop: '1px solid #e5e7eb', paddingTop: '0.35rem', marginTop: '0.25rem' }}>
                  Total: <strong style={{ color: '#2563eb' }}>{order.total?.toFixed(2)}</strong>
                </div>
              </div>
            </div>
          </div>

          {/* Notes */}
          {(order.customerNote || order.ownerNote) && (
            <div className="card">
              <h3 style={{ fontWeight: 700, marginBottom: '0.75rem', fontSize: '0.95rem' }}>Notes</h3>
              {order.customerNote && (
                <div style={{ marginBottom: '0.5rem' }}>
                  <span style={{ fontSize: '0.78rem', color: '#6b7280', display: 'block', marginBottom: '0.25rem' }}>Your note:</span>
                  <p style={{ fontSize: '0.875rem', background: '#f9fafb', padding: '0.6rem', borderRadius: '0.4rem' }}>{order.customerNote}</p>
                </div>
              )}
              {order.ownerNote && (
                <div>
                  <span style={{ fontSize: '0.78rem', color: '#6b7280', display: 'block', marginBottom: '0.25rem' }}>Store note:</span>
                  <p style={{ fontSize: '0.875rem', background: '#f0fdf4', padding: '0.6rem', borderRadius: '0.4rem', color: '#166534' }}>{order.ownerNote}</p>
                </div>
              )}
            </div>
          )}
        </div>

        {/* Right: Downloads & Actions */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
          {/* Order info */}
          <div className="card">
            <h3 style={{ fontWeight: 700, marginBottom: '1rem', fontSize: '0.95rem' }}>Order Info</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem', fontSize: '0.875rem' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span style={{ color: '#6b7280' }}>Order #</span>
                <strong>{order.orderNumber}</strong>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span style={{ color: '#6b7280' }}>Store</span>
                <span>{order.storeName}</span>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span style={{ color: '#6b7280' }}>Date</span>
                <span>{new Date(order.createdAt).toLocaleDateString()}</span>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span style={{ color: '#6b7280' }}>Items</span>
                <span>{order.items?.length}</span>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between', paddingTop: '0.25rem', borderTop: '1px solid #f3f4f6' }}>
                <span style={{ color: '#6b7280' }}>Status</span>
                <StatusBadge status={order.status} />
              </div>
            </div>
          </div>

          {/* Download quotation */}
          <div className="card">
            <h3 style={{ fontWeight: 700, marginBottom: '0.75rem', fontSize: '0.95rem' }}>📋 Quotation</h3>
            <p style={{ fontSize: '0.8rem', color: '#6b7280', marginBottom: '1rem' }}>Download your quotation as PDF or Excel.</p>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
              <a
                href={`/api/customer/orders/${id}/quotation/pdf`}
                target="_blank"
                rel="noreferrer"
                className="btn btn-outline"
                style={{ justifyContent: 'center' }}
              >
                📄 Download Quotation PDF
              </a>
              <a
                href={`/api/customer/orders/${id}/quotation/excel`}
                target="_blank"
                rel="noreferrer"
                className="btn btn-outline"
                style={{ justifyContent: 'center', color: '#16a34a', borderColor: '#16a34a' }}
              >
                📊 Download Quotation Excel
              </a>
            </div>
          </div>

          {/* Invoice download (if available) */}
          {order.invoicePdfPath && (
            <div className="card">
              <h3 style={{ fontWeight: 700, marginBottom: '0.75rem', fontSize: '0.95rem' }}>🧾 Invoice</h3>
              <p style={{ fontSize: '0.8rem', color: '#6b7280', marginBottom: '1rem' }}>
                Your invoice has been generated by the store.
              </p>
              <a
                href={`/uploads/docs/${order.invoicePdfPath.split(/[\\/]/).pop()}`}
                target="_blank"
                rel="noreferrer"
                className="btn btn-success"
                style={{ justifyContent: 'center', width: '100%' }}
              >
                📄 Download Invoice PDF
              </a>
            </div>
          )}

          {/* WhatsApp resend */}
          <div className="card">
            <h3 style={{ fontWeight: 700, marginBottom: '0.75rem', fontSize: '0.95rem' }}>📱 WhatsApp</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem', fontSize: '0.8rem', marginBottom: '1rem' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span>Quotation sent</span>
                <span className={`badge ${order.quotationSentToCustomer ? 'badge-green' : 'badge-gray'}`}>
                  {order.quotationSentToCustomer ? '✓ Sent' : 'Not sent'}
                </span>
              </div>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <span>Invoice sent</span>
                <span className={`badge ${order.invoiceSentToCustomer ? 'badge-green' : 'badge-gray'}`}>
                  {order.invoiceSentToCustomer ? '✓ Sent' : 'Not sent'}
                </span>
              </div>
            </div>
            <button
              className="btn btn-outline"
              style={{ width: '100%', justifyContent: 'center' }}
              onClick={() => handleResendWhatsApp('quotation')}
              disabled={resending}
            >
              {resending ? 'Sending…' : '📤 Resend Quotation to WhatsApp'}
            </button>
          </div>
        </div>
      </div>
    </Layout>
  );
}
